input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var q = input || {};
var projects = Array.isArray(q.projects) ? q.projects : (q.projects ? [q.projects] : []);
var excludeProjects = Array.isArray(q.excludeProjects) ? q.excludeProjects : [];
var dateFrom = q.from || 0;
var dateTo = q.to || 0;
var userWhitelist = Array.isArray(q.userwhitelist) ? q.userwhitelist : [];

var projectNames = [];
var allComponents = [];
var allLabels = [];
var i, p, name, j;

for (i = 0; i < projects.length; i++) {
  p = projects[i];
  if (typeof p === 'string') {
    name = p.trim();
    if (name !== '') {
      projectNames.push(name);
    }
  } else if (typeof p === 'object' && p !== null) {
    name = (p.projectname || '').trim();
    if (name !== '') {
      projectNames.push(name);
    }
    if (Array.isArray(p.components)) {
      for (j = 0; j < p.components.length; j++) {
        allComponents.push(p.components[j]);
      }
    }
    if (Array.isArray(p.labels)) {
      for (j = 0; j < p.labels.length; j++) {
        allLabels.push(p.labels[j]);
      }
    }
  }
}

var excludeProjectNames = [];
for (i = 0; i < excludeProjects.length; i++) {
  if (typeof excludeProjects[i] === 'string' && excludeProjects[i].trim() !== '') {
    excludeProjectNames.push(excludeProjects[i].trim());
  }
}

var componentPattern = '';
if (allComponents.length > 0) {
  componentPattern = allComponents.join('|');
}

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  projectNames: projectNames.length > 0 ? projectNames : ['__NONE__'],
  excludeProjectNames: excludeProjectNames.length > 0 ? excludeProjectNames : ['__NONE__'],
  labels: allLabels.length > 0 ? allLabels : ['__NONE__'],
  componentPattern: componentPattern || '__NOMATCH__',
  dateFrom: dateFrom,
  dateTo: dateTo,
  userWhitelist: userWhitelist.length > 0 ? userWhitelist : ['__NONE__'],
  hasProjectFilter: projectNames.length > 0 ? 1 : 0,
  hasExcludeFilter: excludeProjectNames.length > 0 ? 1 : 0,
  hasDateFrom: dateFrom ? 1 : 0,
  hasDateTo: dateTo ? 1 : 0,
  hasComponentFilter: allComponents.length > 0 ? 1 : 0,
  hasLabelFilter: allLabels.length > 0 ? 1 : 0,
  hasUserWhitelist: userWhitelist.length > 0 ? 1 : 0
})

output_script:
function calculateMedian(arr) {
  if (arr.length === 0) return 0;
  var sorted = arr.slice().sort(function(a, b) { return a - b; });
  var mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[mid - 1] + sorted[mid]) / 2;
  }
  return sorted[mid];
}

var issues = results.main || [];
var resolvedIssues = [];
var i, issue;

for (i = 0; i < issues.length; i++) {
  issue = issues[i];
  if (issue.status === 'TODO' || issue.status === 'IN_PROGRESS') continue;
  if (!issue.created_date || !issue.resolution_date) continue;
  resolvedIssues.push(issue);
}

var result;

if (resolvedIssues.length === 0) {
  result = { error: "No resolved issues found", label: "Median Resolution Time (hours)" };
} else {
  var issuesWithCycleTime = [];
  for (i = 0; i < resolvedIssues.length; i++) {
    var ri = resolvedIssues[i];
    var resolvedAt = new Date(ri.resolution_date);
    if (isNaN(resolvedAt.getTime())) continue;

    var cycleTimeHours;
    if (ri.lead_time_minutes != null && ri.lead_time_minutes > 0) {
      cycleTimeHours = ri.lead_time_minutes / 60;
    } else {
      var createdAt = new Date(ri.created_date);
      if (isNaN(createdAt.getTime())) continue;
      cycleTimeHours = (resolvedAt.getTime() - createdAt.getTime()) / (1000 * 60 * 60);
    }

    if (cycleTimeHours >= 0) {
      issuesWithCycleTime.push({
        resolvedDateStr: resolvedAt.toISOString().split('T')[0],
        cycleTimeHours: cycleTimeHours
      });
    }
  }

  if (issuesWithCycleTime.length === 0) {
    result = { error: "No issues with valid cycle times found" };
  } else {
    var cycleTimesByDay = {};
    for (i = 0; i < issuesWithCycleTime.length; i++) {
      var day = issuesWithCycleTime[i].resolvedDateStr;
      if (!cycleTimesByDay[day]) {
        cycleTimesByDay[day] = [];
      }
      cycleTimesByDay[day].push(issuesWithCycleTime[i].cycleTimeHours);
    }

    var sortedDays = Object.keys(cycleTimesByDay).sort();
    var labels = [];
    var data = [];

    for (i = 0; i < sortedDays.length; i++) {
      var cycleTimes = cycleTimesByDay[sortedDays[i]];
      if (cycleTimes.length > 0) {
        labels.push(sortedDays[i]);
        data.push(calculateMedian(cycleTimes));
      }
    }

    var rollingAvg = [];
    var windowSize = Math.min(7, data.length);
    for (i = 0; i < data.length; i++) {
      var start = Math.max(0, i - windowSize + 1);
      var windowSlice = data.slice(start, i + 1);
      var sum = 0;
      for (var j = 0; j < windowSlice.length; j++) {
        sum += windowSlice[j];
      }
      rollingAvg.push(Math.round(sum / windowSlice.length * 10) / 10);
    }

    var positiveData = data.filter(function(value) { return value > 0; });
    var spread = positiveData.length
      ? Math.max.apply(null, positiveData) / Math.min.apply(null, positiveData)
      : 1;
    var useLog = data.length >= 3 && spread >= 10;
    var yScale = useLog
      ? {
          type: "logarithmic",
          title: { display: true, text: "Hours (log scale)" },
          ticks: {}
        }
      : {
          type: "linear",
          beginAtZero: true,
          title: { display: true, text: "Hours" }
        };

    result = {
      type: "line",
      label: "Median Resolution Time (hours)",
      description: "Each dot shows the median resolution time for issues resolved on that day. The trend line is a 7-day rolling average, smoothing out daily spikes to show whether resolution time is trending up or down. Log scale compresses outliers so daily patterns are easier to read.",
      lastupdate: new Date().getTime(),
      data: {
        labels: labels,
        datasets: [
          {
            label: "Daily Median (hours)",
            data: data,
            showLine: false,
            pointRadius: 5,
            pointHoverRadius: 7,
            pointBackgroundColor: "rgba(75, 192, 192, 0.7)",
            pointBorderColor: "rgba(75, 192, 192, 1)",
            pointBorderWidth: 1,
            backgroundColor: "rgba(75, 192, 192, 0.7)"
          },
          {
            label: "7-day Rolling Avg (hours)",
            data: rollingAvg,
            fill: false,
            borderColor: "rgb(255, 99, 132)",
            borderWidth: 2,
            pointRadius: data.length < 3 ? 3 : 0,
            tension: 0.3
          }
        ],
        options: {
          scales: {
            y: yScale
          },
          plugins: {
            legend: {
              labels: {
                usePointStyle: true,
                pointStyle: "circle",
                padding: 15
              }
            }
          }
        }
      }
    };
  }
}

(result)
